var t=`1415-kaukau-bake`;var n=`world-1415`;var i=`PG`;var s=`oceania`;var u=4;var o=66;var l={en:`Kaukau Bake`,ua:`Печений каукау`};var r={en:`Kaukau is Papua New Guinean sweet potato. This simple baked version uses the tuber as the star.`,ua:`Каукау, батат у кухні Папуа Нової Гвінеї. У цій простій запеченій версії головний продукт, сам коренеплід.`};var c=[{en:`Preheat oven to 200°C. Scrub sweet potatoes well and pat dry; leave skin on if clean and unblemished.`,ua:`Розігрійте духовку до 200°C. Ретельно вимийте й обсушіть батат; шкірку можна залишити, якщо вона чиста й неушкоджена.`,t:[`mise-en-place`],m:8,i:[[`sweet-potato`,1e3,`g`]]},{en:`Rub with a little coconut oil, place on a tray and pierce each tuber a few times.`,ua:`Натріть невеликою кількістю кокосової олії, викладіть на деко та кілька разів проколіть кожен коренеплід.`,t:[`preheating`],m:5,i:[[`coconut-oil`,20,`ml`]]},{en:`Roast for 40–55 minutes, turning once, until a knife passes easily through the middle.`,ua:`Запікайте 40–55 хвилин, один раз перевернувши, доки ніж легко проходитиме до середини.`,t:[`roasting`],m:50,i:[]},{en:`Split, lightly season and serve warm.`,ua:`Розріжте, злегка посоліть і подавайте теплим.`,t:[`seasoning`],m:3,i:[[`sea-salt`,3,`g`]]}];var m={slug:t,id:n,country:`PG`,region:s,servings:4,minutes:66,title:l,text:r,steps:c};export{i as country,m as default,n as id,o as minutes,s as region,u as servings,t as slug,c as steps,r as text,l as title};